CREATE TABLE IF NOT EXISTS community_totals (id INTEGER PRIMARY KEY CHECK(id=1),support INTEGER NOT NULL DEFAULT 0,oppose INTEGER NOT NULL DEFAULT 0,likes INTEGER NOT NULL DEFAULT 0,dislikes INTEGER NOT NULL DEFAULT 0,comments INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO community_totals(id) VALUES(1);
CREATE TABLE IF NOT EXISTS community_votes (session_id TEXT PRIMARY KEY,choice INTEGER NOT NULL CHECK(choice IN(-1,1)),alias TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN(0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS community_votes_public ON community_votes(is_public,updated_at DESC);
CREATE TABLE IF NOT EXISTS community_comments (id TEXT PRIMARY KEY,parent_id TEXT REFERENCES community_comments(id),root_id TEXT NOT NULL,depth INTEGER NOT NULL CHECK(depth BETWEEN 0 AND 5),session_id TEXT NOT NULL,alias TEXT NOT NULL,city TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN('visible','hidden')),likes INTEGER NOT NULL DEFAULT 0,dislikes INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS community_roots ON community_comments(parent_id);
CREATE INDEX IF NOT EXISTS community_thread ON community_comments(root_id);
CREATE INDEX IF NOT EXISTS community_author ON community_comments(session_id,created_at DESC);
CREATE TABLE IF NOT EXISTS community_reactions (session_id TEXT NOT NULL,target_id TEXT NOT NULL,choice INTEGER NOT NULL CHECK(choice IN(-1,1)),PRIMARY KEY(session_id,target_id));
CREATE TABLE IF NOT EXISTS community_reports (comment_id TEXT NOT NULL REFERENCES community_comments(id),session_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(comment_id,session_id));
CREATE INDEX IF NOT EXISTS community_reports_date ON community_reports(created_at DESC);
CREATE TABLE IF NOT EXISTS community_visitors (day TEXT NOT NULL,visitor_key TEXT NOT NULL,country TEXT NOT NULL,region TEXT NOT NULL,device TEXT NOT NULL,path TEXT NOT NULL,first_seen INTEGER NOT NULL,last_seen INTEGER NOT NULL,views INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,visitor_key));
CREATE INDEX IF NOT EXISTS community_visitors_live ON community_visitors(last_seen DESC);
CREATE TABLE IF NOT EXISTS community_pageviews(day TEXT NOT NULL,path TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,path));
CREATE TABLE IF NOT EXISTS community_moderation(id INTEGER PRIMARY KEY AUTOINCREMENT,comment_id TEXT NOT NULL,action TEXT NOT NULL,occurred_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS community_vote_insert AFTER INSERT ON community_votes BEGIN UPDATE community_totals SET support=support+(NEW.choice=1),oppose=oppose+(NEW.choice=-1) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS community_vote_update AFTER UPDATE OF choice ON community_votes BEGIN UPDATE community_totals SET support=support+(NEW.choice=1)-(OLD.choice=1),oppose=oppose+(NEW.choice=-1)-(OLD.choice=-1) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS community_vote_delete AFTER DELETE ON community_votes BEGIN UPDATE community_totals SET support=support-(OLD.choice=1),oppose=oppose-(OLD.choice=-1) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS community_comment_insert AFTER INSERT ON community_comments BEGIN UPDATE community_totals SET comments=comments+(NEW.status='visible') WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS community_comment_status AFTER UPDATE OF status ON community_comments BEGIN UPDATE community_totals SET comments=comments+(NEW.status='visible')-(OLD.status='visible') WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS community_reaction_insert AFTER INSERT ON community_reactions BEGIN UPDATE community_totals SET likes=likes+(NEW.choice=1),dislikes=dislikes+(NEW.choice=-1) WHERE id=1 AND NEW.target_id='campaign'; UPDATE community_comments SET likes=likes+(NEW.choice=1),dislikes=dislikes+(NEW.choice=-1) WHERE id=NEW.target_id; END;
CREATE TRIGGER IF NOT EXISTS community_reaction_update AFTER UPDATE OF choice ON community_reactions BEGIN UPDATE community_totals SET likes=likes+(NEW.choice=1)-(OLD.choice=1),dislikes=dislikes+(NEW.choice=-1)-(OLD.choice=-1) WHERE id=1 AND NEW.target_id='campaign'; UPDATE community_comments SET likes=likes+(NEW.choice=1)-(OLD.choice=1),dislikes=dislikes+(NEW.choice=-1)-(OLD.choice=-1) WHERE id=NEW.target_id; END;
CREATE TRIGGER IF NOT EXISTS community_reaction_delete AFTER DELETE ON community_reactions BEGIN UPDATE community_totals SET likes=likes-(OLD.choice=1),dislikes=dislikes-(OLD.choice=-1) WHERE id=1 AND OLD.target_id='campaign'; UPDATE community_comments SET likes=likes-(OLD.choice=1),dislikes=dislikes-(OLD.choice=-1) WHERE id=OLD.target_id; END;
